def get_controls_by_family(family_name: str) -> List[SecurityControl]:
    return [c for c in NIST_CONTROL_MATRIX.values() if family_name.lower() in c.family.lower()]

def get_control_by_id(control_id: str) -> Optional[SecurityControl]:
    for k, v in NIST_CONTROL_MATRIX.items():
        if v.control_id.upper() == control_id.upper():
            return v
    return None
